	const ACTIVE = "bg-surface-gray-2";
	const IDLE = "bg-transparent";
	const CSS = `.alt-cp-panel { display: none; } .alt-cp-on > .alt-cp-panel { display: block; } .alt-cp-on > :not(.alt-cp-panel) { display: none !important; }`;

